local mod = dmhub.GetModLoading()

-- The [[tornpuzzle:Name]] journal widget: the Director picks an image, a piece
-- count and how much starts taped; the page shows that image torn into irregular
-- pieces scattered on a table. Players drag pieces (or click a piece, then click
-- where it goes). A piece dropped against a true neighbour joins it and tape is
-- laid across the seam; joined pieces move as one. The table is shared through
-- one shared document, so everyone sees the same table.
--
-- Shapes come from TornPuzzleShapes.lua and the tornMask* image resources, both
-- generated by tools/tornpuzzle/make_torn_masks.py. Design brief:
-- principlesnstuff/torn-puzzle-brief.md (Lisa's machine).

---@class RichTornPuzzle: RichTag
--- @field new fun(o?: table): RichTornPuzzle
--- @field identifier string|false
--- @field image string|false
--- @field pieces number
--- @field pretape string
--- @field boardWidth number
RichTornPuzzle = RegisterGameType("RichTornPuzzle", "RichTag")
RichTornPuzzle.tag = "tornpuzzle"
RichTornPuzzle.identifier = false
RichTornPuzzle.image = false
RichTornPuzzle.pieces = 9
RichTornPuzzle.pretape = "none"
RichTornPuzzle.boardWidth = 640

local PUZZLE_DOC = "tornpuzzles"

--Every position is in "image units": 1 = the image's full width (x) or full
--height (y), measured from the table's top-left. The table is TABLE_SCALE images
--wide and tall, which leaves room around the note to scatter pieces.
local TABLE_SCALE = 1.7

--How close (image units, each axis) a dropped group must land to where a
--neighbour expects it before the two join.
local SNAP_DISTANCE = 0.05

--A hold left by a client that vanished mid-drag stops blocking others after this.
local HOLD_EXPIRY_SECONDS = 20

--Loose pieces lie tilted up to this many degrees, like dropped paper.
local MAX_TILT = 8

--Image asset ids of the mask atlases (the tornMask* resources of this mod). Used
--instead of mod.images because resources uploaded since storage moved to R2 have
--URL-form ids, and mod.images turns those into "md5:<url>", which does not load.
--Drop this table once the engine resolves URL-form resource ids.
local MASK_ASSETS = {
    tornMask4 = "537557c5-b8ef-4f10-aa72-b6abc4ae9029",
    tornMask6 = "18d7f05d-c5ab-40bd-8e74-af09cf6d2632",
    tornMask9 = "721c3010-4b34-43de-aa20-92c68fcb32d2",
    tornMask12 = "978b29da-4e15-4cfb-bde6-61d507a9cd7e",
}

local PIECE_OPTIONS = { 4, 6, 9, 12 }
local PRETAPE_FRACTION = { none = 0, few = 0.2, half = 0.5 }

---@class TornGroup
---@field x number origin x: where the image's left edge would sit, image units
---@field y number origin y: where the image's top edge would sit, image units
---@field tilt number degrees; only drawn on single-piece groups
---@field z integer draw order; higher is on top

---@class TornHold
---@field group integer
---@field user string
---@field nonce string

---@class TornBoard
---@field n integer piece count
---@field variant integer which tear pattern in TornPuzzleShapes[n]
---@field mirror boolean pattern flipped left-right for variety
---@field member integer[] piece index -> id of the group it belongs to
---@field groups table<integer, TornGroup>
---@field hold TornHold|nil
---@field done boolean

---@class TornPiece
---@field bbox number[] x1, y1, x2, y2 in image units (y down)
---@field mask any core.Vector4 rect of this piece's mask in its atlas
---@field poly number[] flat x, y outline in image units, for hit-testing

---@class TornSeam
---@field a integer
---@field b integer
---@field mid number[]
---@field angle number degrees in image units (y down)

---@class TornShape
---@field pieces TornPiece[]
---@field seams TornSeam[]
---@field atlas string|nil image id of the mask atlas

function RichTornPuzzle.Create()
    return RichTornPuzzle.new{}
end

---@param tag RichTornPuzzle
---@return integer
local function PieceCount(tag)
    local n = math.tointeger(tonumber(tag.pieces)) or 9
    if TornPuzzleShapes[n] == nil then
        return 9
    end
    return n
end

--The board's key in the shared document: owning page + tag name, so puzzles on
--different pages never share a table. Nil when the tag has no page yet.
---@param tag RichTornPuzzle
---@return string|nil
local function PuzzleKey(tag)
    local doc = tag:GetDocument()
    --an unsaved page has no id yet; reading it would raise, so treat it as no page.
    local docid = doc ~= nil and doc:try_get("id") or nil
    if docid == nil then
        return nil
    end
    local raw = string.format("%s_%s", tostring(docid), tostring(tag.identifier or "default"))
    return (string.gsub(raw, "[^%w_%-]", "_"))
end

--A small seeded generator so every client computes the SAME opening tear for a
--puzzle nobody has touched yet, without anyone having to write it first.
--random(k) returns an integer in 1..k.
---@param seedText string
---@return fun(k: integer): integer
local function SeededRandom(seedText)
    local seed = 7
    for i = 1, #seedText do
        seed = (seed * 31 + string.byte(seedText, i)) % 2147483648
    end
    return function(k)
        seed = (seed * 1103515245 + 12345) % 2147483648
        return (seed // 65536) % k + 1
    end
end

---@param random fun(k: integer): integer
---@return number 0..1
local function RandomFraction(random)
    return (random(10001) - 1) / 10000
end

local g_shapeCache = {}

--Piece and seam geometry for one board, with the left-right mirror applied.
--Mirroring flips the outline and the mask; the image itself is never flipped.
---@param board TornBoard
---@return TornShape
local function ShapeFor(board)
    local cacheKey = string.format("%d:%d:%s", board.n, board.variant, tostring(board.mirror))
    local cached = g_shapeCache[cacheKey]
    if cached ~= nil then
        return cached
    end

    local set = TornPuzzleShapes[board.n]
    local variant = set.variants[board.variant] or set.variants[1]
    local shape = { pieces = {}, seams = {}, atlas = MASK_ASSETS[set.atlas] or mod.images[set.atlas] }

    for i, p in ipairs(variant.pieces) do
        local b, a = p.bbox, p.atlas
        local poly = {}
        if board.mirror then
            for j = 1, #p.poly, 2 do
                poly[j] = 1 - p.poly[j]
                poly[j + 1] = p.poly[j + 1]
            end
            shape.pieces[i] = {
                bbox = { 1 - b[3], b[2], 1 - b[1], b[4] },
                --swapping the x ends of the rect flips the mask horizontally.
                mask = core.Vector4(a[3], a[2], a[1], a[4]),
                poly = poly,
            }
        else
            for j = 1, #p.poly do
                poly[j] = p.poly[j]
            end
            shape.pieces[i] = {
                bbox = { b[1], b[2], b[3], b[4] },
                mask = core.Vector4(a[1], a[2], a[3], a[4]),
                poly = poly,
            }
        end
    end

    for i, s in ipairs(variant.seams) do
        if board.mirror then
            shape.seams[i] = { a = s.a, b = s.b, mid = { 1 - s.mid[1], s.mid[2] }, angle = 180 - s.angle }
        else
            shape.seams[i] = { a = s.a, b = s.b, mid = { s.mid[1], s.mid[2] }, angle = s.angle }
        end
    end

    g_shapeCache[cacheKey] = shape
    return shape
end

--The rectangle (image units, relative to the group origin) covered by a group.
---@param board TornBoard
---@param shape TornShape
---@param groupId integer
---@return number x1, number y1, number x2, number y2
local function GroupBounds(board, shape, groupId)
    local x1, y1, x2, y2 = math.huge, math.huge, -math.huge, -math.huge
    for k, g in ipairs(board.member) do
        if g == groupId then
            local b = shape.pieces[k].bbox
            x1, y1 = math.min(x1, b[1]), math.min(y1, b[2])
            x2, y2 = math.max(x2, b[3]), math.max(y2, b[4])
        end
    end
    return x1, y1, x2, y2
end

--Keep a group's whole footprint on the table.
---@param board TornBoard
---@param shape TornShape
---@param groupId integer
local function ClampGroup(board, shape, groupId)
    local group = board.groups[groupId]
    local x1, y1, x2, y2 = GroupBounds(board, shape, groupId)
    group.x = math.max(-x1, math.min(TABLE_SCALE - x2, group.x))
    group.y = math.max(-y1, math.min(TABLE_SCALE - y2, group.y))
end

---@param board TornBoard
---@return integer
local function GroupCount(board)
    local count = 0
    for _ in pairs(board.groups) do
        count = count + 1
    end
    return count
end

---@param board TornBoard
---@return integer
local function TopZ(board)
    local z = 0
    for _, group in pairs(board.groups) do
        z = math.max(z, group.z)
    end
    return z
end

--Every piece of group `from` joins group `into`.
---@param board TornBoard
---@param from integer
---@param into integer
local function MergeGroups(board, from, into)
    for k, g in ipairs(board.member) do
        if g == from then
            board.member[k] = into
        end
    end
    board.groups[from] = nil
    board.groups[into].tilt = 0
end

--Tear a fresh board: pick a pattern, pre-tape some seams, scatter the groups.
---@param n integer
---@param pretape string
---@param random fun(k: integer): integer
---@return TornBoard
local function Tear(n, pretape, random)
    local set = TornPuzzleShapes[n]
    ---@type TornBoard
    local board = {
        n = n,
        variant = random(#set.variants),
        mirror = random(2) == 2,
        member = {},
        groups = {},
        hold = nil,
        done = false,
    }
    for k = 1, n do
        board.member[k] = k
        board.groups[k] = { x = 0, y = 0, tilt = 0, z = k }
    end

    local shape = ShapeFor(board)
    local order = {}
    for i = 1, #shape.seams do
        order[i] = i
    end
    for i = #order, 2, -1 do
        local j = random(i)
        order[i], order[j] = order[j], order[i]
    end
    local toTape = math.floor((PRETAPE_FRACTION[pretape] or 0) * #shape.seams + 0.5)
    for i = 1, toTape do
        local seam = shape.seams[order[i]]
        local ga, gb = board.member[seam.a], board.member[seam.b]
        if ga ~= gb then
            MergeGroups(board, gb, ga)
        end
    end
    --taping every seam would hand over a finished note; leave the last one loose.
    if GroupCount(board) == 1 and n > 1 then
        local seam = shape.seams[order[1]]
        board.member[seam.b] = seam.b
        board.groups[seam.b] = { x = 0, y = 0, tilt = 0, z = n + 1 }
    end

    for id, group in pairs(board.groups) do
        local x1, y1, x2, y2 = GroupBounds(board, shape, id)
        group.x = -x1 + RandomFraction(random) * (TABLE_SCALE - (x2 - x1))
        group.y = -y1 + RandomFraction(random) * (TABLE_SCALE - (y2 - y1))
        local single = 0
        for _, g in ipairs(board.member) do
            if g == id then
                single = single + 1
            end
        end
        if single == 1 then
            group.tilt = random(MAX_TILT * 2 + 1) - MAX_TILT - 1
        end
    end
    return board
end

---@param n integer
---@return TornBoard
local function SolvedBoard(n)
    ---@type TornBoard
    local board = { n = n, variant = 1, mirror = false, member = {}, groups = {}, hold = nil, done = true }
    for k = 1, n do
        board.member[k] = 1
    end
    local offset = (TABLE_SCALE - 1) / 2
    board.groups[1] = { x = offset, y = offset, tilt = 0, z = 1 }
    return board
end

--Boards travel as short strings rather than nested lists: int-keyed lists can be
--reshaped by the cloud on upload, and a string arrives exactly as written.
---@param board TornBoard
---@return table
local function Encode(board)
    local groups = {}
    for id, g in pairs(board.groups) do
        groups[#groups + 1] = string.format("%d:%.4f:%.4f:%d:%d", id, g.x, g.y, round(g.tilt), g.z)
    end
    return {
        n = board.n,
        variant = board.variant,
        mirror = board.mirror,
        member = table.concat(board.member, ","),
        groups = table.concat(groups, ";"),
        hold = board.hold,
        done = board.done,
    }
end

---@param entry any
---@param n integer
---@return TornBoard|nil
local function Decode(entry, n)
    if type(entry) ~= "table" or entry.n ~= n or type(entry.member) ~= "string" or type(entry.groups) ~= "string" then
        return nil
    end
    local set = TornPuzzleShapes[n]
    local variant = math.tointeger(entry.variant)
    if set == nil or variant == nil or set.variants[variant] == nil then
        return nil
    end
    ---@type TornBoard
    local board = {
        n = n,
        variant = variant,
        mirror = entry.mirror == true,
        member = {},
        groups = {},
        hold = nil,
        done = entry.done == true,
    }
    for part in string.gmatch(entry.groups, "[^;]+") do
        local id, x, y, tilt, z = string.match(part, "^(%d+):([%-%d%.]+):([%-%d%.]+):([%-%d]+):(%d+)$")
        if id ~= nil then
            board.groups[math.tointeger(tonumber(id)) or 0] = {
                x = tonumber(x) or 0,
                y = tonumber(y) or 0,
                tilt = tonumber(tilt) or 0,
                z = math.tointeger(tonumber(z)) or 0,
            }
        end
    end
    for part in string.gmatch(entry.member, "[^,]+") do
        local g = math.tointeger(tonumber(part))
        if g == nil or board.groups[g] == nil then
            return nil
        end
        board.member[#board.member + 1] = g
    end
    if #board.member ~= n then
        return nil
    end
    local hold = entry.hold
    if type(hold) == "table" and type(hold.user) == "string" and math.tointeger(hold.group) ~= nil then
        board.hold = { group = math.tointeger(hold.group) --[[@as integer]], user = hold.user, nonce = tostring(hold.nonce) }
    end
    return board
end

---@param tag RichTornPuzzle
---@return TornBoard
local function ReadBoard(tag)
    local n = PieceCount(tag)
    local key = PuzzleKey(tag)
    if key ~= nil then
        local board = Decode(mod:GetDocumentSnapshot(PUZZLE_DOC).data[key], n)
        if board ~= nil then
            return board
        end
    end
    local seed = string.format("%s:%d:%s", key or "local", n, tostring(tag.pretape))
    return Tear(n, tag.pretape, SeededRandom(seed))
end

---@param tag RichTornPuzzle
---@param board TornBoard
---@param description string
local function WriteBoard(tag, board, description)
    local key = PuzzleKey(tag)
    if key == nil then
        return
    end
    local doc = mod:GetDocumentSnapshot(PUZZLE_DOC)
    doc:BeginChange()
    doc.data[key] = Encode(board)
    doc:CompleteChange(description, {undoable = false})
end

--After a group is put down, join it to every neighbour it now lines up with.
--The group it lands against keeps its place, so a drop never yanks the table.
---@param board TornBoard
---@param shape TornShape
---@param groupId integer
---@return integer groupId the group the dropped pieces belong to now
---@return boolean joined
local function SnapGroup(board, shape, groupId)
    local joined = false
    local merged = true
    while merged do
        merged = false
        for _, seam in ipairs(shape.seams) do
            local ga, gb = board.member[seam.a], board.member[seam.b]
            if ga ~= gb and (ga == groupId or gb == groupId) then
                local other = cond(ga == groupId, gb, ga)
                local mine, theirs = board.groups[groupId], board.groups[other]
                if math.abs(mine.x - theirs.x) < SNAP_DISTANCE and math.abs(mine.y - theirs.y) < SNAP_DISTANCE then
                    theirs.z = math.max(mine.z, theirs.z)
                    MergeGroups(board, groupId, other)
                    groupId = other
                    joined = true
                    merged = true
                    break
                end
            end
        end
    end
    return groupId, joined
end

---@param board TornBoard
---@param shape TornShape
---@return integer taped
local function TapedSeams(board, shape)
    local taped = 0
    for _, seam in ipairs(shape.seams) do
        if board.member[seam.a] == board.member[seam.b] then
            taped = taped + 1
        end
    end
    return taped
end

---@param poly number[]
---@param x number
---@param y number
---@return boolean
local function PointInPolygon(poly, x, y)
    local inside = false
    local count = #poly // 2
    local j = count
    for i = 1, count do
        local xi, yi = poly[i * 2 - 1], poly[i * 2]
        local xj, yj = poly[j * 2 - 1], poly[j * 2]
        if (yi > y) ~= (yj > y) and x < (xj - xi) * (y - yi) / (yj - yi) + xi then
            inside = not inside
        end
        j = i
    end
    return inside
end

---@param userid string
---@return string
local function UserName(userid)
    local info = dmhub.GetSessionInfo(userid)
    if info ~= nil and info.displayName ~= nil and info.displayName ~= "" then
        return info.displayName
    end
    return "Someone"
end

--Read-only views of a puzzle's current table, for tests and dev tooling (e.g.
--driving a drag over the MCP bridge needs to know where pieces are).
---@param tag RichTornPuzzle
---@return TornBoard
function RichTornPuzzle.DebugBoard(tag)
    return ReadBoard(tag)
end

---@param board TornBoard
---@return TornShape
function RichTornPuzzle.DebugShape(board)
    return ShapeFor(board)
end

---@return number tableScale how many image widths/heights the table spans
function RichTornPuzzle.DebugTableScale()
    return TABLE_SCALE
end

function RichTornPuzzle.CreateDisplay(self)
    local m_token = nil
    local m_aspect = 1
    local m_imageInfoFor = nil
    local m_imageSize = nil
    local m_board = nil ---@type TornBoard|nil
    local m_shape = nil ---@type TornShape|nil

    --layout in pixels, recomputed every refresh
    local m_imageW, m_imageH, m_tableW, m_tableH = 1, 1, 1, 1

    --interaction state, local to this client
    local m_pressGroup = nil ---@type integer|nil
    local m_dragGroup = nil ---@type integer|nil
    local m_dragX, m_dragY = 0, 0
    local m_selected = nil ---@type integer|nil
    local m_holdNonce = nil ---@type string|nil
    local m_holdSeen = {} ---@type table<string, number>
    local m_doneAnnounced = false

    local m_piecePanels = {} ---@type Panel[]
    local m_tapePanels = {} ---@type table<integer, Panel>
    local m_builtFor = nil

    local resultPanel
    local table_
    local placeholder
    local statusLabel
    local holdLabel
    local cleanCopyButton
    local directorRow
    local Refresh

    local function Interactive()
        return m_token ~= nil and not m_token.editor and self.image and true or false
    end

    --A hold by another client that has not gone stale. Staleness is timed from when
    --THIS client first saw the hold, so no shared clock is needed.
    ---@param board TornBoard
    ---@return TornHold|nil
    local function OthersHold(board)
        local hold = board.hold
        if hold == nil or hold.user == dmhub.userid then
            return nil
        end
        local seen = m_holdSeen[hold.nonce]
        if seen == nil then
            seen = dmhub.Time()
            m_holdSeen[hold.nonce] = seen
        end
        if dmhub.Time() - seen > HOLD_EXPIRY_SECONDS then
            return nil
        end
        return hold
    end

    local function RequestImageShape()
        if self.image == m_imageInfoFor then
            return
        end
        m_imageInfoFor = self.image
        m_aspect = 1
        m_imageSize = nil
        local requested = self.image
        if not requested then
            return
        end
        --GetImageInfo can call back more than once; only the latest image counts.
        dmhub.GetImageInfo(requested, function(info)
            if mod.unloaded or not resultPanel.valid or requested ~= self.image then
                return
            end
            if info ~= nil and info.width ~= nil and info.width > 0 then
                m_aspect = info.height / info.width
                m_imageSize = { width = info.width, height = info.height }
                Refresh()
            end
        end)
    end

    --(Re)create the piece panels when the tear pattern changes. Pieces never take
    --clicks themselves: their transparent corners would steal grabs, so the table
    --hit-tests outlines instead (see PieceAt).
    local function BuildPieces(board, shape)
        local key = string.format("%d:%d:%s", board.n, board.variant, tostring(board.mirror))
        if m_builtFor == key then
            return
        end
        m_builtFor = key
        m_piecePanels = {}
        m_tapePanels = {}
        for k = 1, board.n do
            m_piecePanels[k] = gui.Panel{
                bgimage = "panels/square.png",
                bgcolor = "white",
                halign = "left",
                valign = "top",
                interactable = false,
            }
        end
        for i = 1, #shape.seams do
            m_tapePanels[i] = gui.Panel{
                classes = {"hidden"},
                bgimage = "panels/square.png",
                bgcolor = "#efe3c2c0",
                halign = "left",
                valign = "top",
                interactable = false,
                --fade is tracked in data: reading a selfStyle value that was never
                --set throws, so selfStyle.opacity cannot be the source of truth.
                data = { shown = false, fade = 1 },
                --a new strip fades in rather than popping.
                thinkTime = 0.03,
                think = function(element)
                    if element.data.fade < 1 then
                        element.data.fade = math.min(1, element.data.fade + 0.12)
                        element.selfStyle.opacity = element.data.fade
                    end
                end,
            }
        end
        --every panel lives on the table from the start (unused tape just hidden);
        --the engine flags panels that are created but never given a parent.
        local children = {}
        for _, panel in ipairs(m_piecePanels) do
            children[#children + 1] = panel
        end
        for _, panel in ipairs(m_tapePanels) do
            children[#children + 1] = panel
        end
        children[#children + 1] = holdLabel
        table_.children = children
    end

    --Place every piece and tape strip. The group being dragged is offset by the
    --drag so far; everything else sits where the board says.
    local function Layout()
        local board, shape = m_board, m_shape
        if board == nil or shape == nil then
            return
        end
        local others = OthersHold(board)

        --draw order: groups by z, the dragged/selected group on top.
        local order = {}
        for id, group in pairs(board.groups) do
            order[#order + 1] = { id = id, z = group.z }
        end
        table.sort(order, function(a, b)
            local az = cond(a.id == m_dragGroup or a.id == m_selected, math.huge, a.z)
            local bz = cond(b.id == m_dragGroup or b.id == m_selected, math.huge, b.z)
            if az == bz then
                return a.id < b.id
            end
            return az < bz
        end)

        local groupSize = {}
        for _, g in ipairs(board.member) do
            groupSize[g] = (groupSize[g] or 0) + 1
        end

        local children = {}
        for _, entry in ipairs(order) do
            local id = entry.id
            local group = board.groups[id]
            local ox, oy = group.x * m_imageW, group.y * m_imageH
            if id == m_dragGroup then
                ox, oy = ox + m_dragX, oy + m_dragY
            end
            local lifted = id == m_dragGroup or id == m_selected
            if lifted then
                --a picked-up group rises off the table so it reads as "in hand".
                oy = oy - 8
            end
            local heldByOther = others ~= nil and others.group == id

            for k, g in ipairs(board.member) do
                if g == id then
                    local piece = shape.pieces[k]
                    local b = piece.bbox
                    local panel = m_piecePanels[k]
                    panel.bgimage = self.image
                    panel.bgimageMask = shape.atlas
                    panel.bgimageMaskRect = piece.mask
                    panel.selfStyle.imageRect = { x1 = b[1], x2 = b[3], y1 = 1 - b[4], y2 = 1 - b[2] }
                    panel.selfStyle.x = ox + b[1] * m_imageW
                    panel.selfStyle.y = oy + b[2] * m_imageH
                    panel.selfStyle.width = (b[3] - b[1]) * m_imageW
                    panel.selfStyle.height = (b[4] - b[2]) * m_imageH
                    --loose pieces keep their tilt until picked up.
                    panel.selfStyle.rotate = cond(groupSize[id] == 1 and not lifted, group.tilt, 0)
                    --only a lone piece grows when lifted: scaling each piece of a
                    --joined group about its own centre would open gaps at the seams.
                    panel.selfStyle.scale = cond(lifted and groupSize[id] == 1, 1.08, 1)
                    panel.selfStyle.opacity = cond(heldByOther, 0.6, 1)
                    children[#children + 1] = panel
                end
            end

            for i, seam in ipairs(shape.seams) do
                if board.member[seam.a] == id and board.member[seam.b] == id then
                    local tape = m_tapePanels[i]
                    --tape length follows the image size; it crosses the seam at right angles.
                    local len = math.max(22, math.min(64, 0.11 * math.min(m_imageW, m_imageH)))
                    local wid = len * 0.34
                    local rad = math.rad(seam.angle)
                    local seamAngle = math.deg(math.atan(math.sin(rad) * m_imageH, math.cos(rad) * m_imageW))
                    --a little per-seam jitter so strips look hand-laid.
                    local jitter = ((i * 37) % 17) - 8
                    tape.selfStyle.width = len
                    tape.selfStyle.height = wid
                    tape.selfStyle.x = ox + seam.mid[1] * m_imageW - len / 2
                    tape.selfStyle.y = oy + seam.mid[2] * m_imageH - wid / 2
                    tape.selfStyle.rotate = -(seamAngle + 90) + jitter
                    if not tape.data.shown then
                        tape.data.shown = true
                        tape.data.fade = 0
                        tape.selfStyle.opacity = 0
                    end
                    tape:SetClass("hidden", false)
                    children[#children + 1] = tape
                end
            end
        end

        --tape on seams that are no longer joined (after a re-tear) disappears.
        for i, seam in ipairs(shape.seams) do
            local tape = m_tapePanels[i]
            if board.member[seam.a] ~= board.member[seam.b] and tape ~= nil then
                tape.data.shown = false
                tape:SetClass("hidden", true)
                children[#children + 1] = tape
            end
        end

        children[#children + 1] = holdLabel
        table_.children = children

        if others ~= nil and board.groups[others.group] ~= nil then
            local group = board.groups[others.group]
            local x1, y1 = GroupBounds(board, shape, others.group)
            holdLabel.text = string.format("%s is holding this", UserName(others.user))
            holdLabel.selfStyle.x = (group.x + x1) * m_imageW
            holdLabel.selfStyle.y = math.max(0, (group.y + y1) * m_imageH - 20)
            holdLabel:SetClass("hidden", false)
        else
            holdLabel:SetClass("hidden", true)
        end
    end

    Refresh = function()
        if not resultPanel.valid then
            return
        end
        RequestImageShape()

        local hasImage = self.image and true or false
        table_:SetClass("collapsed", not hasImage)
        placeholder:SetClass("collapsed", hasImage)
        directorRow:SetClass("collapsed", not hasImage or not dmhub.isDM or m_token == nil or m_token.player == true)
        if not hasImage then
            statusLabel.text = ""
            cleanCopyButton:SetClass("collapsed", true)
            return
        end

        local board = ReadBoard(self)
        local shape = ShapeFor(board)
        m_board, m_shape = board, shape
        --a selection or drag whose group vanished (merged by someone else) is dropped.
        if m_selected ~= nil and board.groups[m_selected] == nil then
            m_selected = nil
        end
        if m_dragGroup ~= nil and board.groups[m_dragGroup] == nil then
            m_dragGroup = nil
        end

        local aspect = math.max(0.4, math.min(2.5, m_aspect))
        m_tableW = self.boardWidth
        m_imageW = m_tableW / TABLE_SCALE
        m_imageH = m_imageW * aspect
        m_tableH = m_imageH * TABLE_SCALE
        table_.selfStyle.width = m_tableW
        table_.selfStyle.height = m_tableH
        resultPanel.selfStyle.width = m_tableW

        BuildPieces(board, shape)
        Layout()

        if board.done then
            statusLabel.text = "Pieced together"
        else
            statusLabel.text = string.format("%d of %d seams taped", TapedSeams(board, shape), #shape.seams)
        end
        cleanCopyButton:SetClass("collapsed", not board.done)
    end

    --The group whose piece outline is under a table-pixel point, topmost first.
    ---@param px number
    ---@param py number
    ---@return integer|nil
    local function PieceAt(px, py)
        local board, shape = m_board, m_shape
        if board == nil or shape == nil then
            return nil
        end
        local order = {}
        for id, group in pairs(board.groups) do
            order[#order + 1] = { id = id, z = group.z }
        end
        table.sort(order, function(a, b) return a.z > b.z end)

        local groupSize = {}
        for _, g in ipairs(board.member) do
            groupSize[g] = (groupSize[g] or 0) + 1
        end

        for _, entry in ipairs(order) do
            local group = board.groups[entry.id]
            for k, g in ipairs(board.member) do
                if g == entry.id then
                    local b = shape.pieces[k].bbox
                    local x, y = px, py
                    if groupSize[g] == 1 and group.tilt ~= 0 then
                        --undo the piece's tilt (counter-clockwise on screen) about its centre.
                        local cx = (group.x + (b[1] + b[3]) / 2) * m_imageW
                        local cy = (group.y + (b[2] + b[4]) / 2) * m_imageH
                        local t = math.rad(group.tilt)
                        local dx, dy = x - cx, y - cy
                        x = cx + dx * math.cos(t) - dy * math.sin(t)
                        y = cy + dx * math.sin(t) + dy * math.cos(t)
                    end
                    local ux = x / m_imageW - group.x
                    local uy = y / m_imageH - group.y
                    if ux >= b[1] and ux <= b[3] and uy >= b[2] and uy <= b[4]
                        and PointInPolygon(shape.pieces[k].poly, ux, uy) then
                        return entry.id
                    end
                end
            end
        end
        return nil
    end

    ---@return number px, number py
    local function MouseOnTable()
        local point = table_.mousePoint
        return point.x * m_tableW, (1 - point.y) * m_tableH
    end

    ---@param groupId integer|nil
    local function SetHold(groupId)
        local board = ReadBoard(self)
        if groupId == nil then
            if board.hold ~= nil and board.hold.nonce == m_holdNonce then
                board.hold = nil
                WriteBoard(self, board, "Put down torn puzzle piece")
            end
            m_holdNonce = nil
            return
        end
        m_holdNonce = dmhub.GenerateGuid()
        board.hold = { group = groupId, user = dmhub.userid, nonce = m_holdNonce }
        WriteBoard(self, board, "Pick up torn puzzle piece")
    end

    --Put a group down at a new origin, join it to any neighbours it now lines up
    --with, and announce the finished note if that was the last join.
    ---@param groupId integer
    ---@param x number
    ---@param y number
    local function PlaceGroup(groupId, x, y)
        local board = ReadBoard(self)
        local shape = ShapeFor(board)
        local group = board.groups[groupId]
        if group == nil then
            return
        end
        group.x, group.y = x, y
        group.tilt = 0
        group.z = TopZ(board) + 1
        --snap BEFORE clamping: a neighbour's matching spot can hang off the table
        --edge, and clamping first made that join impossible. The joined group is
        --then nudged back onto the table as a whole.
        groupId = SnapGroup(board, shape, groupId)
        ClampGroup(board, shape, groupId)
        if board.hold ~= nil and board.hold.nonce == m_holdNonce then
            board.hold = nil
        end
        m_holdNonce = nil

        local finished = not board.done and GroupCount(board) == 1
        if finished then
            board.done = true
            local only = next(board.groups)
            if only ~= nil then
                local offset = (TABLE_SCALE - 1) / 2
                board.groups[only].x, board.groups[only].y = offset, offset
            end
        end
        WriteBoard(self, board, "Move torn puzzle piece")
        if finished and not m_doneAnnounced then
            m_doneAnnounced = true
            local name = self.identifier or "the torn note"
            chat.Send(string.format("The party pieced together %s.", name))
        end
        Refresh()
    end

    holdLabel = gui.Label{
        classes = {"hidden", "sizeXs"},
        width = "auto",
        height = "auto",
        halign = "left",
        valign = "top",
        bgimage = "panels/square.png",
        bgcolor = "#000000aa",
        hpad = 4,
        borderBox = true,
        interactable = false,
        text = "",
    }

    table_ = gui.Panel{
        flow = "none",
        width = self.boardWidth,
        height = self.boardWidth,
        halign = "left",
        bgimage = "panels/square.png",
        bgcolor = "#ffffff0d",
        border = 1,
        borderColor = "#ffffff26",
        draggable = true,
        dragMove = false,

        press = function(element)
            m_pressGroup = nil
            if not Interactive() or m_board == nil or m_board.done then
                return
            end
            local px, py = MouseOnTable()
            m_pressGroup = PieceAt(px, py)
        end,

        beginDrag = function(element)
            m_dragGroup = nil
            local groupId = m_pressGroup
            if groupId == nil or m_board == nil or m_board.done then
                return
            end
            local others = OthersHold(m_board)
            if others ~= nil and others.group == groupId then
                return
            end
            if m_selected ~= nil then
                m_selected = nil
            end
            m_dragGroup = groupId
            m_dragX, m_dragY = 0, 0
            SetHold(groupId)
        end,

        dragging = function(element, target)
            if m_dragGroup == nil then
                return
            end
            m_dragX, m_dragY = element.dragDelta.x, element.dragDelta.y
            Layout()
        end,

        drag = function(element, target)
            local groupId = m_dragGroup
            if groupId == nil or m_board == nil then
                return
            end
            local group = m_board.groups[groupId]
            local dx, dy = element.dragDelta.x, element.dragDelta.y
            m_dragGroup = nil
            if group == nil then
                SetHold(nil)
                Refresh()
                return
            end
            PlaceGroup(groupId, group.x + dx / m_imageW, group.y + dy / m_imageH)
        end,

        --The no-drag path: click a piece to pick it up, then click where it goes.
        click = function(element)
            if not Interactive() or m_board == nil or m_board.done then
                return
            end
            local px, py = MouseOnTable()
            local hit = PieceAt(px, py)
            if m_selected == nil then
                if hit == nil then
                    return
                end
                local others = OthersHold(m_board)
                if others ~= nil and others.group == hit then
                    return
                end
                m_selected = hit
                SetHold(hit)
                Layout()
                return
            end
            local selected = m_selected
            m_selected = nil
            if hit == selected then
                SetHold(nil)
                Refresh()
                return
            end
            --centre the picked-up group on the clicked point.
            local x1, y1, x2, y2 = GroupBounds(m_board, ShapeFor(m_board), selected)
            PlaceGroup(selected, px / m_imageW - (x1 + x2) / 2, py / m_imageH - (y1 + y2) / 2)
        end,

        --holds expire on a timer, so re-check them even when nothing is written.
        thinkTime = 1,
        think = function(element)
            if m_board ~= nil and m_board.hold ~= nil and m_dragGroup == nil then
                Layout()
            end
        end,

        holdLabel,
    }

    placeholder = gui.Label{
        classes = {"collapsed"},
        width = 340,
        height = 64,
        halign = "left",
        bgimage = "panels/square.png",
        bgcolor = "#00000044",
        border = 1,
        borderColor = "#99999977",
        fontSize = 14,
        color = "#aaaaaa",
        textAlignment = "center",
        text = "Torn puzzle: choose an image in the annotations strip below.",
    }

    statusLabel = gui.Label{
        classes = {"sizeS"},
        width = "auto",
        height = "auto",
        halign = "left",
        valign = "center",
        text = "",
    }

    cleanCopyButton = gui.Button{
        classes = {"sizeXs", "collapsed"},
        text = "View clean copy",
        width = 120,
        height = 22,
        hmargin = 6,
        valign = "center",
        press = function(element)
            if not self.image then
                return
            end
            local size = m_imageSize or { width = 1024, height = 1024 }
            GameHud.instance:ViewCompendiumEntryModal(ImageDocument.new{
                imageid = self.image,
                width = size.width,
                height = size.height,
            })
        end,
    }

    directorRow = gui.Panel{
        flow = "horizontal",
        width = "auto",
        height = "auto",
        halign = "right",
        valign = "center",
        gui.Button{
            classes = {"sizeXs"},
            text = "Re-tear",
            width = 72,
            height = 22,
            hmargin = 2,
            press = function(element)
                GameHud.instance:ModalDialog{
                    title = "Tear it up again?",
                    width = 640,
                    height = 280,
                    buttonsHalign = "center",
                    buttons = {
                        {
                            text = "Cancel",
                            escapeActivates = true,
                            click = function() end,
                        },
                        {
                            text = "Re-tear",
                            click = function()
                                if mod.unloaded or not resultPanel.valid then
                                    return
                                end
                                m_selected, m_dragGroup, m_doneAnnounced = nil, nil, false
                                WriteBoard(self, Tear(PieceCount(self), self.pretape, math.random), "Re-tear torn puzzle")
                                Refresh()
                            end,
                        },
                    },
                    gui.Panel{
                        width = 520,
                        height = 80,
                        halign = "center",
                        valign = "center",
                        gui.Label{
                            classes = {"modalMessage"},
                            text = "The table's progress will be lost.",
                        },
                    },
                }
            end,
        },
        gui.Button{
            classes = {"sizeXs"},
            text = "Solve",
            width = 72,
            height = 22,
            hmargin = 2,
            press = function(element)
                m_selected, m_dragGroup = nil, nil
                WriteBoard(self, SolvedBoard(PieceCount(self)), "Solve torn puzzle")
                Refresh()
            end,
        },
    }

    resultPanel = gui.Panel{
        flow = "vertical",
        width = self.boardWidth,
        height = "auto",
        halign = "left",
        valign = "top",
        vmargin = 4,
        monitorGame = mod:GetDocumentPath(PUZZLE_DOC),
        refreshGame = function(element)
            --a remote write mid-drag would snap the held pieces back; wait for the drop.
            if m_dragGroup == nil then
                Refresh()
            end
        end,
        refreshTag = function(element, tag, match, token)
            self = tag or self
            m_token = token
            Refresh()
        end,
        --the annotation editors change image/pieces on the tag object directly
        --with no event, so poll cheaply while a page is in edit mode.
        thinkTime = 0.5,
        think = function(element)
            if m_token ~= nil and m_token.editor then
                Refresh()
            end
        end,

        table_,
        placeholder,
        gui.Panel{
            flow = "horizontal",
            width = "100%",
            height = 26,
            tmargin = 2,
            statusLabel,
            cleanCopyButton,
            directorRow,
        },
    }

    return resultPanel
end

function RichTornPuzzle.CreateEditor(self)
    return gui.Panel{
        flow = "none",
        width = 96,
        height = "100%",
        refreshEditor = function(element, richTag)
            self = richTag or self
        end,
        gui.Button{
            classes = {"settingsButton", "sizeXxs"},
            halign = "right",
            valign = "top",
            press = function(element)
                if element.popup ~= nil then
                    element.popup = nil
                    return
                end
                local pieceOptions = {}
                for _, n in ipairs(PIECE_OPTIONS) do
                    pieceOptions[#pieceOptions + 1] = { id = tostring(n), text = tostring(n) }
                end
                element.popupsInheritStyles = true
                element.popup = gui.Panel{
                    classes = {"bordered", "bg"},
                    width = "auto",
                    height = "auto",
                    flow = "vertical",
                    pad = 8,
                    borderBox = true,
                    gui.Label{
                        classes = {"sizeS"},
                        width = "auto",
                        height = "auto",
                        text = "Pieces:",
                    },
                    gui.Dropdown{
                        options = pieceOptions,
                        idChosen = tostring(PieceCount(self)),
                        change = function(dropdown)
                            ---@cast dropdown Dropdown
                            self.pieces = tonumber(dropdown.idChosen) or 9
                        end,
                    },
                    gui.Label{
                        classes = {"sizeS"},
                        width = "auto",
                        height = "auto",
                        tmargin = 6,
                        text = "Start taped:",
                    },
                    gui.Dropdown{
                        options = {
                            { id = "none", text = "None" },
                            { id = "few", text = "A few" },
                            { id = "half", text = "About half" },
                        },
                        idChosen = PRETAPE_FRACTION[self.pretape] ~= nil and self.pretape or "none",
                        change = function(dropdown)
                            ---@cast dropdown Dropdown
                            self.pretape = tostring(dropdown.idChosen)
                        end,
                    },
                    gui.Label{
                        classes = {"sizeS"},
                        width = "auto",
                        height = "auto",
                        tmargin = 6,
                        text = "Board width:",
                    },
                    gui.Slider{
                        width = 200,
                        labelWidth = 48,
                        height = 20,
                        minValue = 360,
                        maxValue = 960,
                        handleSize = "100%",
                        value = self.boardWidth,
                        change = function(slider)
                            self.boardWidth = round(slider.value)
                        end,
                    },
                }
            end,
        },
        gui.IconEditor{
            width = 64,
            height = 64,
            halign = "center",
            valign = "center",
            library = "Avatar",
            value = self.image or nil,
            change = function(element)
                self.image = element.value
            end,
        },
    }
end

MarkdownDocument.RegisterRichTag(RichTornPuzzle)
